"""Prepare one reviewable introduction per researched organisation. Does not send."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
rows=json.loads((ROOT/'outreach/growth-prospects-2026-10-19.json').read_text(encoding='utf8'))
out=['# Prepared school and operator introductions','','Prepared 19 October 2026. These 32 introductions are saved for review, not sent or scheduled. Contact routes are sourced in the prospect shortlist. Screen objections and prior contact before use. Where only a form is available, use its correct enquiry route or ask the organisation for the relevant team; do not invent an email address.']
for r in rows:
    school=r['type']=='schools'
    signals=r['evidence']
    relevance=('Your published International Baccalaureate provision makes practical field investigation a potentially relevant conversation.' if any('Baccalaureate' in x or 'IB Diploma' in x for x in signals) else 'Your published boarding programme makes a tailored residential learning experience a potentially relevant conversation.' if 'boarding' in signals else 'I am getting in touch to ask whether a tailored residential field-science programme could be relevant to your pupils.') if school else ('Your published science and educational travel offer prompted me to ask whether a specialist local field-science programme could fit your portfolio.' if 'science' in signals else 'Your published educational travel offer prompted me to ask whether a specialist programme in Piemonte could fit your school portfolio.')
    subject='Field science in Piemonte - '+r['name'] if school else 'Piemonte educational delivery partnership - '+r['name']
    contact='; '.join(x['email'] for x in r['emails'][:1]) or r['contact']
    out+=['',f"## {r['name']}",'',f'Contact route: {contact}',f"Official source: {r['website']}",'',f'Subject: {subject}','','Hello,','',relevance,'',"I'm Adam Rose from EcoWise Italy. We design and deliver tailored outdoor education in Piemonte, north-west Italy, combining environmental science and ecology with practical investigation, teamwork, storytelling, environmental art and nature awareness.",'',"Our October 2026 public trip report describes our tenth annual five-day environmental science and field sampling trip with Beau Soleil College, including terrestrial and aquatic field methods and data collection for DP biology and environmental studies projects.",'']
    if school:
        out += ["Could you point me to the colleague responsible for biology/environmental studies fieldwork or residential trips? We can explore a five-day/four-night format or a longer tailored programme around your pupils' aims. Delivery is available year-round, subject to confirming dates and programme fit.",'',"We select the programme location and book suitable accommodation and food on the school's behalf. The school normally arranges its main travel and pays the programme, accommodation/food and travel separately. Every trip receives a bespoke quote.",'',"There is a six-page teacher planning guide here, with a five-day example and the practical arrangements:"]
    else:
        out += ["I'm interested in a supplier conversation with your educational product, contracting or partnerships team. EcoWise Italy can contribute educational design and local programme delivery, site selection and coordination of accommodation and food bookings. Your organisation's travel/package role and supplier terms would be agreed directly before any offer is made.",'',"Our two-page partner brief and teacher guide explain the offer and responsibilities:"]
    out += ['https://ecowiseitaly.com/school-trips-italy/#teacher-resources','',"Would a short conversation with the relevant colleague be useful? I reply personally within 24 hours.",'','Best wishes,','Adam Rose','EcoWise Italy','schools@ecowiseitaly.com','+39 342 136 3274','', 'You are receiving this introduction at a public organisational contact route because it appears relevant to educational travel. If it is not relevant, reply "no thanks" and we will not contact this address again.','EcoWise Italy, Via Mazzini 97, 14020 Aramengo, Asti, Italy.']
(ROOT/'outreach/prepared-introductions-2026-10-19.md').write_text('\n'.join(out)+'\n',encoding='utf8')
print(f'Prepared {len(rows)} individual organisation drafts; sent zero.')
